class Nagetier extends Sprite //erzeugt eine Klasse Hammy - das "extends Sprite" erstmal ignorieren!
{
    /**
     * Attribute
     */
   int gegesseneKörner = 0; //int heißt in Java "ganze Zahl"
   String name = "Hammy"; // String ist ein Text

    /**
     * Spezielle Methode: Konstruktor, erstellt ein neues Objekt der Klasse 
     */
   Nagetier() {
      super(250, 250, SpriteLibrary.Hamster);
      println("Gegessene Körner: " + gegesseneKörner); 
   }

    /** 
     * Methoden
     */
   void geheNachRechts() {
      setAngle(90);
      move(10, 0);
   }

   void geheNachOben() {
      setAngle(180);
      move(0, -10);
   }

   // Diese spezielle Methode wird durchgehend, 
   // etwa 30 mal pro Sekunde aufgerufen bzw. ausgeführt. 
   void act() {
      if(isKeyDown("w")) {
         geheNachOben();
      } else if(isKeyDown("d")) {
         geheNachRechts();
      }
      esseKorn();
   }




   // Es wird überprüft, ob ein Korn berührt wird. Falls ja, wird es gegessen
   void esseKorn() {
      Sprite sprite = getFirstCollidingSprite(1);
      if(sprite != null) {
         println("Korn gegessen"); 
         sprite.destroy();
         gegesseneKörner = gegesseneKörner + 1; 
         println("Gegessene Körner: " + gegesseneKörner); 
      }
   }
}

